
/* ---------- TIMELINE EVENTS ----------
   y = numeric sort key (negative = BCE). yr = display string. */
D.events = [
/* ===== e1 Prehistory & the Vedic Hills ===== */
{id:"ev-palaeo", era:"e1", y:-40000, yr:"c. 40,000 BCE", t:"Palaeolithic hunters in the Shivaliks", big:1,
 s:"Stone tools from the Banganga, Sirsa, Markanda and Swan valleys place humans in the HP foothills in the Lower Palaeolithic.",
 blocks:[["p","Hand-axes and cleavers of Soan-type industry have been recovered from the <b>Banganga valley (Kangra), the Sirsa and Markanda valleys (Nalagarh and Sirmaur), the Swan valley (Una)</b> and near <b>Guler and Dehra</b>. These are the earliest traces of human presence in the state."],
 ["p","Later neolithic and chalcolithic material comes from the same Shivalik belt. The hill interiors preserve almost nothing prehistoric — settlement follows the low valleys."]],
 rel:["d-una","d-sirmaur","t-ancientsources"]},
{id:"ev-kols", era:"e1", y:-2500, yr:"c. 2500 BCE", t:"The Kolarian peoples — the first inhabitants",
 s:"Kols and Mundas, Proto-Australoid speakers, are taken as the earliest identifiable inhabitants of the hills.",
 blocks:[["p","Pushed north out of the Indo-Gangetic plains, the <b>Kolarian (Kol, Munda)</b> peoples are the first population the sources name. Vedic literature calls them <b>Dasas, Dasyus and Nishadas</b>; later Puranic literature calls them <b>Kinnaras, Nagas and Yakshas</b>."],
 ["p","The usual sequence taught for HP is: <b>Kols/Mundas → Kiratas (Mongoloid) → Aryans/Khasas</b>."]],
 rel:["t-ancientsources","ev-shambara"]},
{id:"ev-shambara", era:"e1", y:-1500, yr:"c. 1500 BCE", t:"Shambara and the ninety-nine forts", big:1,
 s:"The Rig Veda records the Dasyu king Shambara holding 99 forts between the Beas and the Yamuna, defeated by Divodasa.",
 blocks:[["p","The <b>Rig Veda</b> names <b>Shambara</b>, a powerful <b>Dasyu</b> chief who held <b>99 forts in the hills between the Beas and the Yamuna</b>. He was defeated after a forty-year struggle by <b>Divodasa</b>, the Aryan king, in the battle sometimes located at Udbhraj."],
 ["p","This is the earliest literary reference to the territory of Himachal Pradesh and is asked almost every year."]],
 rel:["t-ancientsources","ev-kols"]},
{id:"ev-khasas", era:"e1", y:-1000, yr:"c. 1000 BCE", t:"Khasas settle and form tribal republics",
 s:"The Khasa branch of the Aryans enters through the Pamir–Kashmir route and organises into janapadas.",
 blocks:[["p","The <b>Khasas</b> entered the hills from the north-west and settled in small clan republics, each under an elected <i>mavana</i>. Their speech is treated as the ancestor of the <b>Pahari</b> languages, and the <b>Kanets</b> of the interior are usually identified as their descendants."],
 ["p","These republics are the <b>janapadas</b> that the Mahabharata and Panini will later name."]],
 rel:["t-janapadas","t-tribes"]},

/* ===== e2 Janapadas ===== */
{id:"ev-trigarta", era:"e2", y:-800, yr:"c. 8th–9th c. BCE", t:"Trigarta founded by Susharma Chandra", big:1,
 s:"The Katoch line traces itself to Susharma Chandra, who fought for the Kauravas and built Nagarkot.",
 blocks:[["p","<b>Trigarta</b> — the land of three rivers — is the oldest named polity in the region. Tradition credits its founding to <b>Susharma Chandra</b>, who in the Mahabharata attacked <b>Virata</b>, king of Matsya, on the Kaurava side, and who is said to have built the fort of <b>Nagarkot (Kangra)</b>."],
 ["p","<b>Panini</b> (5th century BCE) mentions Trigarta and calls its people <b>Ayudhajivi sangha</b> — a confederacy living by arms. Trigarta coins are <b>square</b>, with Brahmi and Kharoshthi legends."]],
 rel:["s-kangra","t-janapadas","d-kangra"]},
{id:"ev-audumbara", era:"e2", y:-200, yr:"c. 2nd c. BCE", t:"Audumbara republic and its coinage", big:1,
 s:"The Audumbaras, claiming descent from Vishwamitra, struck copper and silver coins bearing the name Mahadeva.",
 blocks:[["p","The <b>Audumbaras</b> held the Beas–Ravi tract on the trade road from <b>Takshashila to the Ganga valley</b>. The Mahabharata makes them descendants of the sage <b>Vishwamitra</b> of the Kaushika gotra. They began as a <b>republic with an elected king</b> and later turned monarchical."],
 ["p","Their <b>copper and silver coins</b>, in <b>Brahmi and Kharoshthi</b>, have been found at <b>Kangra, Jwalamukhi, Pathankot, Gurdaspur and Hoshiarpur</b>; several bear the name <b>Mahadeva</b>. Their economy rested on sheep-rearing and woollen goods."]],
 rel:["t-janapadas","t-ancientsources"]},
{id:"ev-kuninda", era:"e2", y:-100, yr:"c. 1st c. BCE", t:"Kuninda coins of Amoghabhuti",
 s:"The Kunindas of the Beas–Yamuna tract issue silver coins naming Raja Amoghabhuti.",
 blocks:[["p","The <b>Kunindas (Kulindas)</b> lived between the <b>Beas, Sutlej and Yamuna</b> — the Shimla and Sirmaur hills. Their name is usually derived from the <b>Kalindi (Yamuna)</b>. The <b>Kanets</b> are taken as their modern descendants."],
 ["p","Their <b>silver coins carry the name Amoghabhuti</b>; copper coins used Brahmi for local circulation and Prakrit in Kharoshthi for trade beyond the hills."]],
 rel:["t-janapadas","d-shimla","d-sirmaur"]},
{id:"ev-kuluta-coin", era:"e2", y:100, yr:"c. 1st–2nd c. CE", t:"The Kuluta coin of Virayasa",
 s:"A copper coin reading 'Rajna Virayasasya Kulutasya' proves an independent Kuluta kingdom in the upper Beas.",
 blocks:[["p","A copper coin found in Kullu bears the legend <b>'Rajna Virayasasya Kulutasya'</b> — of Virayasa, king of the Kulutas — in Brahmi, with a Kharoshthi legend on the reverse. It is the single most cited piece of evidence for the antiquity of Kullu."],
 ["p","Kuluta is called <b>Kulanthapitha</b>, 'the end of the habitable world', in Sanskrit sources."]],
 rel:["s-kullu","t-janapadas","d-kullu"]},

/* ===== e3 Empires ===== */
{id:"ev-alexander", era:"e3", y:-326, yr:"326 BCE", t:"Alexander halts at the Beas", big:1,
 s:"Alexander's army reaches the Beas and turns back; Coenus raises twelve altars on the bank.",
 blocks:[["p","Alexander advanced to the <b>Beas (Hyphasis)</b> and there his army refused to go further. The republican peoples of the hills — the <b>Ayudhajivi sanghas</b> — had massed against him. His general <b>Coenus</b> raised <b>twelve great altars</b> on the bank to mark the limit of the advance; no trace of them survives."]],
 rel:["t-janapadas","t-ancientsources"]},
{id:"ev-maurya", era:"e3", y:-322, yr:"c. 322 BCE", t:"Parvataka allies with Chandragupta Maurya",
 s:"The hill chief Parvataka, ruling between the Ravi and the Yamuna, joins Chandragupta against the Nandas.",
 blocks:[["p","<b>Parvataka</b> (identified by some with Porus's kinsman Parvateshwar), whose territory lay between the <b>Ravi and the Yamuna</b>, allied with <b>Chandragupta Maurya</b> and Chanakya. The hills passed under loose Mauryan suzerainty."]],
 rel:["ev-ashoka","t-ancientsources"]},
{id:"ev-ashoka", era:"e3", y:-250, yr:"c. 250 BCE", t:"Ashoka sends Buddhism into the hills", big:1,
 s:"Ashoka despatches the monk Majjhima to the Himalaya and raises a stupa in the Kullu valley.",
 blocks:[["p","After the third Buddhist council Ashoka sent <b>Majjhima</b> with a mission to the <b>Himalayan country</b>. A <b>stupa in the Kullu valley</b> is attributed to Ashoka, and his <b>rock edict at Kalsi</b> stands just beyond the Sirmaur border on the Yamuna."],
 ["p","Buddhism took lasting hold only in the trans-Himalayan valleys — Lahaul, Spiti and Kinnaur."]],
 rel:["d-kullu","t-monasteries","ev-maurya"]},
{id:"ev-indogreek", era:"e3", y:-150, yr:"c. 2nd c. BCE", t:"Indo-Greek coins reach the hills",
 s:"Coins of Apollodotus found at Tappa Mewa in Hamirpur mark Indo-Greek commercial contact.",
 blocks:[["p","After the Shungas lost their grip the hill republics asserted independence and issued their own coins. <b>Twenty-one coins of Apollodotus</b> were found at <b>Tappa Mewa (Hamirpur)</b>, and <b>thirty-one</b> at <b>Jwalamukhi</b>, evidence of Indo-Greek trade along the Beas."]],
 rel:["d-hamirpur","t-ancientsources"]},
{id:"ev-kushan", era:"e3", y:78, yr:"c. 1st–3rd c. CE", t:"Kushan overlordship under Kanishka",
 s:"The Kushans hold the hills loosely; forty copper coins on the Kalka–Kasauli road record their reach.",
 blocks:[["p","Under <b>Kanishka</b> the hill states became tributary but retained autonomy. <b>Forty Kushan copper coins</b> found on the <b>Kalka–Kasauli road</b> are the standard evidence cited."]],
 rel:["d-solan","t-ancientsources"]},
{id:"ev-gupta", era:"e3", y:350, yr:"c. 350 CE", t:"Samudragupta's Allahabad pillar names the hill kings",
 s:"The Prayag prashasti lists the Himalayan frontier rulers as accepting Gupta paramountcy without war.",
 blocks:[["p","The <b>Allahabad (Prayag) pillar inscription</b> of <b>Samudragupta</b>, composed by Harisena, lists the frontier states that submitted and paid tribute without being conquered. The hill kingdoms of the Punjab Himalaya are among them — the first epigraphic notice of the region in an imperial record."]],
 rel:["t-ancientsources"]},
{id:"ev-hunas", era:"e3", y:500, yr:"c. 500 CE", t:"The Hunas — Toramana and Mihirakula",
 s:"Huna incursions break Gupta power; the Gaddis and Gujjars trace descent from them.",
 blocks:[["p","<b>Toramana</b> and his son <b>Mihirakula</b> pushed into the north-west and shattered Gupta authority. Traditions among the <b>Gaddis and Gujjars</b> of Himachal claim descent from the Huna settlers who remained in the hills."]],
 rel:["t-tribes","d-chamba"]},
{id:"ev-hiuentsang", era:"e3", y:635, yr:"630–644 CE", t:"Hiuen Tsang travels through the hills", big:1,
 s:"The Chinese pilgrim visits Jalandhara, Kuluta, Lahaul and Srughna, leaving the first outside description.",
 blocks:[["p","<b>Hiuen Tsang</b> spent four months at <b>Jalandhara</b> with King <b>Utito (Utitas)</b>, and travelled on to <b>Kuluta (Kullu)</b>, <b>Lahaul</b> and <b>Srughna (Sirmaur)</b>. His account is the first external description of the hill country and notes both Buddhist monasteries and Hindu temples in use."]],
 rel:["t-ancientsources","s-kullu","d-lahaul"]},
{id:"ev-nirmand", era:"e3", y:640, yr:"7th century", t:"The Nirmand copper plate",
 s:"A land grant of Mahasamanta Maharaja Samudrasena — the earliest copper-plate record in HP.",
 blocks:[["p","The <b>Nirmand copper plate</b> (Kullu district) records a grant by <b>Mahasamanta Maharaja Samudrasena</b> of the Sena family, showing the Senas as subordinate rulers under Kuluta. It is the earliest copper-plate charter found in Himachal Pradesh."],
 ["p","The other early epigraphs to remember are the <b>Pathyar and Kanihara rock inscriptions (Kangra)</b>, the <b>Hatkoti cave inscription (Shimla)</b> and the <b>Salanu inscription (Mandi)</b>."]],
 rel:["t-ancientsources","d-kullu"]},

/* ===== e4 Rise of the hill states ===== */
{id:"ev-chamba-founded", era:"e4", y:550, yr:"c. 550 CE", t:"Chamba founded at Bharmour by Maru Varman", big:1,
 s:"Maru Varman establishes the state at Brahmpura (Bharmour), the oldest continuous line in the region.",
 blocks:[["p","<b>Maru Varman</b> founded the state with its seat at <b>Brahmpura (Bharmour)</b>. About 130 years later <b>Meru Varman</b> built the shrines of the <b>Chaurasi complex</b> — Lakshana Devi, Shakti Devi (Chhatrari) and Narsingh — whose metal images were cast by the artist <b>Gugga</b>, and whose inscriptions are the oldest dated records in Himachal."]],
 rel:["s-chamba","d-chamba","t-temples"]},
{id:"ev-kahlur", era:"e4", y:697, yr:"697 CE", t:"Kahlur (Bilaspur) founded by Bir Chand",
 s:"A Chandel Rajput from Chanderi establishes Kahlur on the lower Sutlej.",
 blocks:[["p","<b>Bir Chand</b>, said to have come from <b>Chanderi in Bundelkhand</b>, founded <b>Kahlur</b> with its seat at Kot Kahlur. The state later gave rise to <b>Hindur (Nalagarh)</b>."]],
 rel:["s-kahlur","d-bilaspur"]},
{id:"ev-suket", era:"e4", y:765, yr:"c. 765 CE", t:"Suket founded by Bir Sen",
 s:"The elder branch of the Sena house establishes itself at Pangna.",
 blocks:[["p","<b>Bir Sen (Vir Sen)</b> founded <b>Suket</b> with its capital at <b>Pangna</b>. The younger branch of the same house later founded <b>Mandi</b>, and the two quarrelled until both were merged into one district in 1948."]],
 rel:["s-suket","s-mandi","d-mandi"]},
{id:"ev-chamba-town", era:"e4", y:920, yr:"c. 920 CE", t:"Sahil Varman moves the capital to Chamba", big:1,
 s:"The new town is named for his daughter Champavati, who by tradition gave her life for its water channel.",
 blocks:[["p","<b>Sahil Varman</b> shifted the seat from Bharmour down the Ravi and named the new town <b>Chamba</b> after his daughter <b>Champavati</b>. The tradition that she sacrificed herself so the water channel would flow is commemorated by the <b>Sui Mata fair</b>."],
 ["p","He also began the <b>Laxmi Narayan temple group</b>, the principal shrine of the state."]],
 rel:["s-chamba","d-chamba","t-fairs","t-temples"]},
{id:"ev-ghazni", era:"e4", y:1009, yr:"1009 CE", t:"Mahmud Ghazni sacks Nagarkot", big:1,
 s:"The first Muslim invasion of the hills strips the temple treasury of Kangra.",
 blocks:[["p","<b>Mahmud of Ghazni</b> took <b>Nagarkot (Kangra)</b> and carried off the accumulated treasure of the <b>Brajeshwari temple</b> — the event is described in the <b>Tarikh-i-Yamini</b> of Utbi. The fort was recovered by the hill chiefs afterwards."],
 ["p","It is the first of four famous captures of Kangra fort: <b>1009 Ghazni, 1360 Firoz Shah Tughlaq, 1620 Jahangir, 1809 Ranjit Singh</b>."]],
 rel:["s-kangra","d-kangra","b-kangra1620"]},
{id:"ev-sirmaur-founded", era:"e4", y:1095, yr:"c. 1095 CE", t:"Sirmaur founded",
 s:"Tradition credits Raja Rasaloo; the old capital at Sirmauri Tal was later destroyed by a flood.",
 blocks:[["p","The Sirmaur line, whose rulers carry the suffix <b>Prakash</b>, is traditionally traced to <b>Raja Rasaloo</b> of Jaisalmer. The first capital, <b>Sirmauri Tal</b>, was said to have been destroyed by a flood, after which the seat moved and finally settled at <b>Nahan (1621)</b>."]],
 rel:["s-sirmaur","d-sirmaur"]},
{id:"ev-hindur", era:"e4", y:1100, yr:"1100 CE", t:"Hindur (Nalagarh) founded by Ajai Chand",
 s:"A Kahlur prince establishes the state guarding the Sutlej exit into the plains.",
 blocks:[["p","<b>Ajai Chand</b>, of the Kahlur house, founded <b>Hindur</b> with its capital at <b>Nalagarh</b>. Its forts of <b>Ramgarh</b> and <b>Malaun</b> would decide the Anglo-Gorkha war seven centuries later."]],
 rel:["s-nalagarh","b-malaun","d-solan"]},
{id:"ev-tughlaq", era:"e4", y:1360, yr:"1360 CE", t:"Firoz Shah Tughlaq raids Nagarkot",
 s:"The sultan takes the fort and carries off Sanskrit manuscripts from the Jwalamukhi temple library.",
 blocks:[["p","<b>Firoz Shah Tughlaq</b> invaded Kangra, took the fort, and removed <b>1,300 Sanskrit manuscripts</b> from the library of the <b>Jwalamukhi</b> temple; some were translated into Persian as the <b>Dalail-i-Firoz Shahi</b>. Muhammad bin Tughlaq had raided the same area in 1337."]],
 rel:["s-kangra","d-kangra","t-temples"]},
{id:"ev-timur", era:"e4", y:1398, yr:"1398 CE", t:"Timur's passage through the lower hills",
 s:"Timur's army moves along the Shivalik fringe, taking forts on the way back from Delhi.",
 blocks:[["p","Returning from the sack of Delhi, <b>Timur</b> moved along the foot of the hills, taking forts in the Nagarkot and Sirmaur tracts. The disruption weakened the lower states and let the interior states consolidate."]],
 rel:["s-kangra","s-sirmaur"]},
{id:"ev-guler", era:"e4", y:1405, yr:"1405 CE", t:"Guler founded by Hari Chand",
 s:"Presumed dead in a hunting accident, the Katoch prince returns to find his brother enthroned and founds a new state.",
 blocks:[["p","<b>Hari Chand</b> of Kangra fell into a disused well while hunting and was given up for dead. When he emerged his brother <b>Karam Chand</b> had been enthroned, so Hari Chand founded <b>Haripur-Guler</b> instead. Three and a half centuries later Guler would produce the painting style from which the Kangra school grew."]],
 rel:["s-guler","t-pahari-painting"]},

/* ===== e5 Mughals ===== */
{id:"ev-mandi-founded", era:"e5", y:1526, yr:"1526", t:"Ajbar Sen founds Mandi town", big:1,
 s:"In the year of the first battle of Panipat, the Sena raja moves across the Beas and lays out Mandi.",
 blocks:[["p","<b>Ajbar Sen</b> shifted his seat from Bhiuli across the Beas and founded <b>Mandi</b>, building the <b>Bhootnath temple</b> at its centre. The date is easy to hold because it is the year of the <b>first battle of Panipat</b>."]],
 rel:["s-mandi","d-mandi","t-temples"]},
{id:"ev-akbar-tribute", era:"e5", y:1572, yr:"1556–1605", t:"The hill states become Mughal tributaries", big:1,
 s:"Under Akbar the Punjab hill states pay tribute, surrender hostages, and lose their plains territory.",
 blocks:[["p","<b>Akbar</b> brought the hill chiefs into the imperial system: they paid tribute, sent sons as hostages to court, and served in Mughal campaigns. Kangra's plains territory — the <b>Rajgiri</b> tract of 66 villages — was resumed, and <b>Raja Jai Chand</b> of Kangra was imprisoned. <b>Todar Mal</b> carried out the settlement."],
 ["p","The pattern held for a century and a half: internal autonomy in exchange for tribute and troops. It is the same bargain the British would later formalise in sanads."]],
 rel:["s-kangra","t-mughal-relations","b-kangra1620"]},
{id:"ev-nurpur-name", era:"e5", y:1620, yr:"c. 1620", t:"Dhameri is renamed Nurpur",
 s:"The Pathania capital takes the name of Empress Nur Jahan.",
 blocks:[["p","The town and state of <b>Dhameri</b> were renamed <b>Nurpur</b> in Jahangir's reign in honour of <b>Nur Jahan</b>. Raja <b>Basu</b> and his successors served the Mughals in the Deccan and in Kabul."]],
 rel:["s-nurpur","d-kangra"]},
{id:"ev-jagatsingh-revolt", era:"e5", y:1641, yr:"1641–42", t:"Jagat Singh of Nurpur rebels against Shah Jahan",
 s:"The raja who helped take Kangra fort turns on the empire and is reduced after a long siege.",
 blocks:[["p","<b>Jagat Singh</b> of Nurpur, rewarded for his part in the capture of Kangra in 1620, later revolted, seized Mau and Taragarh and defied Shah Jahan. The imperial army under <b>Prince Murad Baksh</b> and <b>Asalat Khan</b> reduced his forts; he submitted and was restored to service."]],
 rel:["s-nurpur","b-kangra1620","t-mughal-relations"]},
{id:"ev-raghunath", era:"e5", y:1651, yr:"c. 1651", t:"Raghunathji is brought to Kullu", big:1,
 s:"Raja Jagat Singh atones for the Durga Dutt affair by installing an image from Ayodhya and ruling as its regent.",
 blocks:[["p","Told that a brahmin of Tipri, <b>Durga Dutt</b>, had immolated himself and his family after a false accusation of hoarding pearls, Raja <b>Jagat Singh</b> was advised to expiate the sin by bringing an image of <b>Raghunath</b> from Ayodhya, installing it as the ruler of Kullu, and governing as its regent."],
 ["p","From this comes <b>Kullu Dussehra</b>, which begins on <b>Vijaya Dashami</b> — when Dussehra ends elsewhere — and runs for seven days, with the village deities of the valley assembling before Raghunathji."]],
 rel:["s-kullu","d-kullu","t-fairs","t-temples"]},
{id:"ev-paonta", era:"e5", y:1685, yr:"1685–88", t:"Guru Gobind Singh at Paonta Sahib", big:1,
 s:"Invited by Raja Medini Prakash of Sirmaur, the Guru builds Paonta on the Yamuna.",
 blocks:[["p","<b>Guru Gobind Singh</b> came to Sirmaur at the invitation of <b>Raja Medini Prakash</b> and founded <b>Paonta Sahib</b> on the Yamuna, where he stayed for about four years. Much of the <b>Dasam Granth</b> is associated with this period, and his court of fifty-two poets sat here."]],
 rel:["s-sirmaur","d-sirmaur","b-bhangani","t-sikh-relations"]},

/* ===== e6 Sansar Chand & the Sikhs ===== */
{id:"ev-ghamand", era:"e6", y:1758, yr:"1758", t:"Ghamand Chand made Nazim of the Jalandhar Doab",
 s:"Ahmad Shah Abdali appoints the Katoch raja governor — the beginning of Kangra's revival.",
 blocks:[["p","With Mughal power gone, <b>Ahmad Shah Abdali</b> appointed <b>Ghamand Chand</b> of Kangra as <b>Nazim of the Jalandhar Doab</b>. Unable to take the fort of Kangra, still held by a Mughal garrison, he built a new capital at <b>Tira Sujanpur</b>."]],
 rel:["s-kangra","p-sansarchand","d-hamirpur"]},
{id:"ev-jaisingh-fort", era:"e6", y:1774, yr:"1774", t:"Jai Singh Kanhaiya takes Kangra fort by stratagem",
 s:"The Sikh misldar tricks the starving Mughal garrison into surrender.",
 blocks:[["p","<b>Jai Singh Kanhaiya</b>, of the Kanhaiya misl, obtained the fort from its last Mughal keeper <b>Saif Ali Khan</b>'s successors by a ruse, holding it until 1785–86."]],
 rel:["s-kangra","p-sansarchand","t-sikh-relations"]},
{id:"ev-sansar-fort", era:"e6", y:1786, yr:"1786", t:"Sansar Chand recovers Kangra fort", big:1,
 s:"The Katoch raja regains his ancestral fortress and begins two decades of supremacy over the hills.",
 blocks:[["p","<b>Sansar Chand II</b>, who succeeded in 1775 at the age of ten, recovered <b>Kangra fort</b> from Jai Singh Kanhaiya in 1786. Over the next twenty years he reduced <b>Chamba, Mandi, Suket, Kullu, Kahlur, Nurpur, Guler, Jaswan, Siba and Kutlehr</b> to tribute — the greatest extent of Katoch power."],
 ["p","At <b>Sujanpur Tira</b> and <b>Alampur</b> his court became the centre of the <b>Kangra school of painting</b>. His ambition to build a Katoch kingdom in the plains brought him into collision first with Ranjit Singh and then with the Gorkhas."]],
 rel:["s-kangra","p-sansarchand","t-pahari-painting","b-mahalmorian","d-hamirpur"]},
{id:"ev-jwalamukhi-treaty", era:"e6", y:1809, yr:"1809", t:"Treaty of Jwalamukhi — Kangra fort to Ranjit Singh", big:1,
 s:"Sansar Chand buys Sikh help against the Gorkhas by ceding the fort; the Gorkhas are driven from Kangra.",
 blocks:[["p","Besieged in Kangra fort for four years, <b>Sansar Chand</b> appealed to <b>Maharaja Ranjit Singh</b>. By the agreement concluded at <b>Jwalamukhi in 1809</b> the Sikhs drove <b>Amar Singh Thapa</b>'s Gorkhas out of the Kangra valley — and took the fort for themselves, together with 66 villages."],
 ["p","Sansar Chand was left a tributary. Kangra remained Sikh until the British annexation of <b>1846</b>."]],
 rel:["b-kangra1809","p-sansarchand","t-sikh-relations","s-kangra","ev-gorkha-kangra"]},
{id:"ev-lahore-treaty", era:"e6", y:1846, yr:"1846", t:"First Anglo-Sikh War ends — the hills pass to the British", big:1,
 s:"Under the Treaty of Lahore the Sikh trans-Sutlej hill territories, including Kangra, Kullu and Lahaul-Spiti, are ceded.",
 blocks:[["p","The <b>Treaty of Lahore (9 March 1846)</b> transferred the Sikh hill possessions to the East India Company. <b>Kangra, Kullu, Lahaul and Spiti</b> were formed into the <b>district of Kangra</b> under Punjab, with headquarters first at Kangra and later at Dharamshala."],
 ["p","This is the administrative fact behind 1966: because Kangra was made part of Punjab in 1846, it had to be transferred to Himachal Pradesh by the <b>Punjab Reorganisation Act</b> a century and a quarter later."]],
 rel:["s-kangra","ev-punjab-reorg","t-colonial-admin","d-kangra"]},

/* ===== e7 Gorkha ===== */
{id:"ev-gorkha-rise", era:"e7", y:1768, yr:"1768", t:"Prithvi Narayan Shah unifies Nepal",
 s:"The Gorkha state is consolidated and begins a westward expansion towards Kashmir.",
 blocks:[["p","<b>Prithvi Narayan Shah</b> completed the conquest of the Kathmandu valley in 1768. His successors set out to build a Gorkha empire <b>from Nepal to Kashmir</b>, which brought them across Kumaon and Garhwal to the Sutlej."]],
 rel:["ev-gorkha-sirmaur","t-gorkha"]},
{id:"ev-gorkha-sirmaur", era:"e7", y:1803, yr:"1803", t:"Amar Singh Thapa takes Sirmaur", big:1,
 s:"The first hill state falls; the Gorkhas cross the Yamuna and occupy Nahan.",
 blocks:[["p","<b>Amar Singh Thapa</b> crossed the Yamuna and overran <b>Sirmaur</b>, driving out <b>Karam Prakash II</b>. Within two years the Gorkhas held the Shimla hills as far as the Sutlej — some thirty small states submitted."],
 ["p","Gorkha rule was remembered for its severity: heavy revenue demands, <b>begar</b> (forced labour), and the slave trade. This is the 'nature' of the invasion the syllabus asks about."]],
 rel:["s-sirmaur","t-gorkha","b-jaithak","d-sirmaur"]},
{id:"ev-gorkha-kangra", era:"e7", y:1806, yr:"1806", t:"Gorkhas defeat Sansar Chand at Mahal Morian", big:1,
 s:"Invited by the hill chiefs whom Sansar Chand had subdued, Amar Singh Thapa breaks Katoch power.",
 blocks:[["p","Resentful of Sansar Chand's exactions, the hill chiefs — led by Kahlur — invited the Gorkhas in. At <b>Mahal Morian</b> (Hamirpur) in <b>1806</b>, <b>Amar Singh Thapa</b> defeated Sansar Chand, who fled first to <b>Sujanpur Tira</b> and then into <b>Kangra fort</b>, which he held under siege for four years."],
 ["p","The Gorkhas overran the Kangra valley but could never take the fort. In 1809 Ranjit Singh's intervention drove them back across the Sutlej for good."]],
 rel:["b-mahalmorian","p-sansarchand","ev-jwalamukhi-treaty","t-gorkha","d-hamirpur"]},
{id:"ev-anglo-gorkha", era:"e7", y:1814, yr:"1 November 1814", t:"The Anglo-Gorkha War begins", big:1,
 s:"The Company declares war; Gillespie is killed at Kalanga and the hill campaign turns on Jaithak and Malaun.",
 blocks:[["p","Border disputes in the Tarai brought war. Of the four British columns, the two that matter for Himachal were <b>Major-General Rollo Gillespie</b>'s, which was destroyed at <b>Kalanga (Nalapani)</b> where Gillespie was killed on <b>31 October 1814</b>, and <b>Major-General David Ochterlony</b>'s, which advanced against Amar Singh Thapa in the Shimla hills."],
 ["p","Ochterlony's method was to detach the hill chiefs from the Gorkhas by promising restoration — which is exactly what the sanads of 1815 delivered."]],
 rel:["b-jaithak","b-malaun","t-gorkha","p-ochterlony"]},
{id:"ev-malaun", era:"e7", y:1815, yr:"15 May 1815", t:"Malaun falls; Amar Singh Thapa capitulates", big:1,
 s:"The Gorkha commander surrenders the last fort west of the Sutlej and withdraws to Nepal.",
 blocks:[["p","After the loss of <b>Ramgarh</b> and the death of his son <b>Bhakti Thapa</b> in the assault, <b>Amar Singh Thapa</b> surrendered <b>Malaun</b> on terms and withdrew across the Sutlej. The Gorkhas were allowed to march out with their arms; many of their soldiers were promptly enlisted by the British."],
 ["p","The <b>Nasiri battalion</b> — later the 1st Gorkha Rifles — was raised from them and stationed at <b>Subathu</b>. Its Jutogh detachment would mutiny in 1857."]],
 rel:["b-malaun","t-gorkha","ev-1857","s-nalagarh"]},
{id:"ev-segauli", era:"e7", y:1816, yr:"2 Dec 1815 / ratified 4 March 1816", t:"Treaty of Segauli (Sugauli)", big:1,
 s:"Nepal cedes everything west of the Kali, accepts a British Resident, and the hill states are restored under sanads.",
 blocks:[["p","The treaty was <b>signed on 2 December 1815</b> and <b>ratified on 4 March 1816</b>. Nepal gave up <b>all territory west of the Kali river</b> — Kumaon, Garhwal and the hill states up to the Sutlej — surrendered the disputed Tarai, accepted a <b>British Resident at Kathmandu</b>, and conceded the right to recruit Gorkhas."],
 ["p","<b>Consequences for Himachal:</b> the hill states were restored to their rajas, but as <b>protected states holding British sanads</b> — internal autonomy, no external relations, no war, succession subject to recognition. Some territory was retained directly: the <b>Subathu, Kotgarh, Kotkhai</b> tracts and the ground that became <b>Shimla</b>. A <b>Superintendent of Hill States</b> was appointed, with his seat at Subathu."],
 ["note","Exam hook","Segauli dates: signed 2 December 1815, ratified 4 March 1816. Boundary: the Kali river. It ends Gorkha rule in Himachal and begins British paramountcy."]],
 rel:["b-segauli","t-gorkha","t-colonial-admin","ev-shimla-summer-capital"]},

/* ===== e8 British ===== */
{id:"ev-subathu", era:"e8", y:1815, yr:"1815", t:"Subathu becomes the first hill cantonment",
 s:"The seat of the Superintendent of Hill States and of the newly raised Nasiri battalion.",
 blocks:[["p","Taken from the Gorkhas, <b>Subathu</b> became the first British cantonment in the hills and the residence of the officer supervising the restored states. The administrative frame built here — Political Agent, sanad, recognition of succession — governed the hill states until 1947."]],
 rel:["t-colonial-admin","d-solan","ev-segauli"]},
{id:"ev-shimla-summer-capital", era:"e8", y:1864, yr:"1822 · 1864 · 1939", t:"Shimla becomes the summer capital of British India", big:1,
 s:"From Kennedy's first house in 1822 to the seat of the Government of India from 1864 to 1939.",
 blocks:[["p","Land taken from <b>Keonthal</b> and <b>Bhajji</b> after the Gorkha war became the station of Shimla. <b>Lieutenant Charles Pratt Kennedy</b> built the first permanent house here in <b>1822</b>. <b>Lord Amherst</b> visited in 1827, and in <b>1864 Lord Lawrence</b> made Shimla the <b>summer capital of the Government of India</b> — a status it held until 1939."],
 ["ul",["<b>Rothney Castle</b> — home of <b>A. O. Hume</b>, where the plan for the Indian National Congress took shape (founded 1885).","<b>Viceregal Lodge</b>, completed 1888 under Lord Dufferin; now the Indian Institute of Advanced Study.","<b>Gaiety Theatre</b>, 1887; <b>Christ Church</b>, 1857; the Town Hall and the Mall.","<b>Simla Conference</b>, 25 June – 14 July 1945 — the Wavell Plan; it failed over the Muslim League's claim to nominate all Muslim members.","The <b>Simla Agreement</b> between India and Pakistan was signed here on 2 July 1972."]]],
 rel:["s-keonthal","t-british-shimla","d-shimla","ev-kalka-railway"]},
{id:"ev-ramsingh", era:"e8", y:1848, yr:"1848", t:"Ram Singh Pathania's revolt", big:1,
 s:"The first armed resistance to British rule in the hills, raised in Nurpur during the Second Anglo-Sikh War.",
 blocks:[["p","<b>Ram Singh Pathania</b>, wazir of Nurpur, rose against the British in 1848 in the name of the minor heir <b>Jaswant Singh</b>. He seized the fort of Shahpur Kandi and held out in the Nurpur hills before being defeated near <b>Shahpur</b>, betrayed, and transported to <b>Singapore</b>, where he died in 1849."],
 ["p","The syllabus period for the freedom movement in Himachal — <b>1848 to 1948</b> — is dated from this revolt."]],
 rel:["s-nurpur","p-ramsingh","d-kangra","t-freedom"]},
{id:"ev-1857", era:"e8", y:1857, yr:"1857", t:"The Revolt of 1857 in the hills", big:1,
 s:"Kasauli and Jutogh rise, Kullu's princes are hanged, and Bushahr alone refuses to help the British.",
 blocks:[["p","The rising in the hills began at <b>Kasauli</b>, where <b>Subedar Bhim Singh</b> led about eighty men of the guard, seized the treasury, and joined the <b>Nasiri battalion</b> at <b>Jutogh</b> near Shimla. The Europeans of Shimla fled to Kotgarh and Junga."],
 ["ul",["<b>Pratap Singh and Vir Singh</b> of Kullu were hanged at <b>Dharamshala on 3 August 1857</b>.","<b>Ram Prasad Bairagi</b> was executed at Ambala.","<b>Bushahr</b> was the <b>only hill state that neither assisted the British nor supplied troops</b>; Raja <b>Shamsher Singh</b> sheltered Bhim Singh.","Most other rulers — Patiala, Nalagarh, Bilaspur, Keonthal, Bhagat, Mandi, Sirmaur — actively helped the British and were rewarded with sanads, titles and grants in 1858–60."]],
 ["note","Exam hook","1857 in HP = Kasauli (Bhim Singh) → Jutogh (Nasiri battalion) → Kullu (Pratap Singh and Vir Singh hanged 3 August) → Bushahr (the one state that stayed out)."]],
 rel:["s-bushahr","s-kullu","d-solan","d-kullu","t-colonial-admin","t-freedom"]},
{id:"ev-dujjam", era:"e8", y:1906, yr:"1859 · 1883 · 1906", t:"Anti-begar risings: Dum Koti, Jugga and Dujjam",
 s:"Three peasant movements against forced labour — the deepest root of the Himachal freedom struggle.",
 blocks:[["p","Long before the Praja Mandals, hill peasants were resisting <b>begar</b> (unpaid forced labour), <b>reeth</b> (bride-price/wife-sale custom) and arbitrary levies."],
 ["ul",["<b>Dum Koti rising, 1859</b> — in Bushahr, against begar and the raja's officials.","<b>Jugga movement, 1883–88</b> — in Bilaspur (Kahlur), a sustained refusal of forced labour.","<b>Dujjam movement, 1906</b> — non-cooperation in Rampur Bushahr.","<b>Satyanand Stokes</b> at Kotgarh campaigned against begar from 1909; the practice was formally ended in the Shimla hills in the early 1920s."]]],
 rel:["s-bushahr","s-kahlur","p-stokes","t-freedom","d-shimla"]},
{id:"ev-kalka-railway", era:"e8", y:1903, yr:"9 November 1903", t:"The Kalka–Shimla Railway opens",
 s:"96 km, 103 tunnels and over 800 bridges; a UNESCO World Heritage Site since 2008.",
 blocks:[["p","Built by the Delhi–Ambala–Kalka Railway Company and opened on <b>9 November 1903</b>. It runs <b>96 km</b> on 2 ft 6 in gauge with <b>103 tunnels</b> (the longest, Barog tunnel no. 33) and more than <b>800 bridges</b>. It was inscribed as part of the <b>Mountain Railways of India</b> UNESCO World Heritage Site in <b>2008</b>."]],
 rel:["t-british-shimla","d-shimla","d-solan"]},
{id:"ev-kangra-quake", era:"e8", y:1905, yr:"4 April 1905", t:"The Kangra earthquake", big:1,
 s:"About 20,000 people die; Kangra fort, Dharamshala and the Baijnath temple are wrecked.",
 blocks:[["p","An earthquake of roughly <b>magnitude 7.8</b> struck the Kangra valley on the morning of <b>4 April 1905</b>, killing about <b>20,000 people</b> and destroying much of Kangra town, Dharamshala and McLeodganj. <b>Kangra fort</b> was reduced to the ruin seen today; the <b>Baijnath temple</b> survived with damage."],
 ["p","Himachal Pradesh lies largely in <b>seismic zones IV and V</b>, and the 1905 event is the standard reference in disaster-management answers."]],
 rel:["d-kangra","s-kangra","t-disaster"]},
{id:"ev-mandi-conspiracy", era:"e8", y:1914, yr:"1914–15", t:"The Mandi Conspiracy", big:1,
 s:"Ghadar party emissaries plan risings in Mandi and Suket; Bhai Hirda Ram is sentenced.",
 blocks:[["p","Emissaries of the <b>Ghadar party</b>, founded by <b>Lala Hardayal</b> in San Francisco, reached Mandi and Suket to recruit for a general rising. The plan included killing the Superintendent and the wazir, looting the treasury and blowing up the <b>Beas bridge</b> at Mandi."],
 ["p","It collapsed; only the <b>Nagchala robbery</b> was carried out. <b>Bhai Hirda Ram</b> was sentenced to death (commuted to transportation), and <b>Swami Krishnanand (Hardev)</b> emerged from the affair as a leading figure."]],
 rel:["s-mandi","d-mandi","t-freedom"]},

/* ===== e9 Praja Mandal ===== */
{id:"ev-prajamandal", era:"e9", y:1939, yr:"1930s", t:"The Praja Mandals are formed", big:1,
 s:"State-by-state people's organisations demand responsible government inside the princely states.",
 blocks:[["p","The <b>All India States People's Conference (1927)</b> gave the movement in the princely states a national frame; in the hills it took the form of <b>Praja Mandals</b> — people's associations demanding civil rights, an end to begar, and responsible government under the raja."],
 ["ul",["<b>Chamba</b> — People's Defence League / Servants of the People, 1932 and 1936.","<b>Mandi</b> — Praja Mandal, 1936.","<b>Baghat</b> — 1938.","<b>Himalayan Riyasati Praja Mandal</b>, Shimla — the umbrella body, with <b>Bhagmal Sautha</b> as president and <b>Pandit Padam Dev</b> as secretary.","<b>Kunihar</b> — 1939; <b>Dhami</b> — 13 July 1939; <b>Sirmaur</b> — 1939 and again 1944.","<b>Bilaspur</b> — 1945, under <b>Daulat Ram Sankhyan</b> and <b>Narotam Dutt Shastri</b>."]],
 ["note","Disputed","Founding years for several Praja Mandals differ between sources (the Himalayan Riyasati Praja Mandal is dated both 1938 and 1939). Where a year is contested, give the movement and the leader — those are stable."]],
 rel:["ev-dhami","ev-kunihar","p-padamdev","p-bhagmalsautha","t-freedom","ev-hhsrc"]},
{id:"ev-kunihar", era:"e9", y:1939.5, yr:"9 July 1939", t:"The Kunihar agreement",
 s:"Rana Hardev Singh concedes the Praja Mandal's demands in writing — a rare constitutional victory.",
 blocks:[["p","The <b>Kunihar Praja Mandal</b> forced <b>Rana Hardev Singh</b> to accept its conditions in a written agreement on <b>9 July 1939</b>, a week before the Dhami firing. An earlier agitation of <b>1920</b> under <b>Gauri Shankar</b> and <b>Baba Kanshi Ram</b> had prepared the ground."]],
 rel:["s-kunihar","p-kanshiram","ev-dhami","t-freedom"]},
{id:"ev-dhami", era:"e9", y:1939.6, yr:"16 July 1939", t:"The Dhami firing", big:1,
 s:"The first firing on a popular movement in the Himachal hills; Durga Das is killed at Halog.",
 blocks:[["p","The <b>Dhami Prem Prachani Sabha</b> was banned and its leader <b>Bhagmal Sautha</b> arrested as he led a procession to present demands to <b>Rana Dalip Singh</b>. At <b>Halog</b> the Rana's men opened fire on the crowd. <b>Durga Das</b> was killed and many were injured — the <b>first firing on a popular movement in the hills</b>."],
 ["p","<b>Mansa Ram</b> and <b>Dharam Das</b> were arrested with Sautha. <b>Jawaharlal Nehru</b> took up the case and the lawyer <b>Duni Chand</b> was sent to enquire; a delegation including <b>Rajkumari Amrit Kaur</b> carried the matter to Gandhi and Nehru."],
 ["note","Disputed","Sources differ on whether one or two people died and on the names — Durga Das is given everywhere, Uma Dutt in some accounts. Quote Durga Das and note the dispute."]],
 rel:["s-dhami","p-bhagmalsautha","p-amritkaur","d-shimla","t-freedom"]},
{id:"ev-pajhota", era:"e9", y:1942, yr:"1942", t:"The Pajhota agitation", big:1,
 s:"Sirmaur's 'Bhai do na pai' rising — Quit India in the hills; the administration is kept out for months.",
 blocks:[["p","In the <b>Pajhota</b> area of Sirmaur, peasants refused to give men or money for the British war effort that their raja <b>Rajendra Prakash</b> was supporting. The slogan was <b>'Bhai do, na pai'</b> — neither brother nor penny."],
 ["p","Led by <b>Vaid Surat Singh</b>, with <b>Laxmi Singh, Miyan Chuchu and Basti Ram Pahari</b>, the movement kept the state administration out of the area for several months. It is treated as an <b>extension of the Quit India Movement</b> of August 1942 and is the most important single episode of the hill freedom struggle after Dhami."]],
 rel:["s-sirmaur","d-sirmaur","t-freedom","ev-prajamandal"]},
{id:"ev-hhsrc", era:"e9", y:1946, yr:"8–10 March 1946", t:"Himalayan Hill States Regional Council formed at Mandi", big:1,
 s:"Delegates of the hill states meet and demand a single hill province; Y. S. Parmar is elected president.",
 blocks:[["p","Representatives of the hill states met at <b>Mandi from 8 to 10 March 1946</b> and constituted the <b>Himalayan Hill States Regional Council</b>, with <b>Dr. Y. S. Parmar</b> as president and <b>Pandit Padam Dev</b> as secretary. Its demand was a <b>single administrative unit for the hill states</b> — the political idea that became Himachal Pradesh."],
 ["p","A second session at <b>Sanjauli (Shimla)</b> pressed the case, and the <b>Solan convention of 26–28 January 1948</b> resolved on merger."]],
 rel:["p-parmar","p-padamdev","ev-hp-formation","t-freedom"]},
{id:"ev-suket-satyagraha", era:"e9", y:1948.1, yr:"18 February 1948", t:"The Suket Satyagraha", big:1,
 s:"The last popular movement against a hill ruler, launched from Tattapani under Pandit Padam Dev.",
 blocks:[["p","Launched from <b>Tattapani on 18 February 1948</b> under <b>Pandit Padam Dev</b>, the Suket Satyagraha was directed against Raja <b>Lakshman Sen</b>. Volunteers marched on Sundernagar; the state's resistance collapsed and Suket acceded."],
 ["p","It is remembered as the movement that completed the integration — within two months the Chief Commissioner's Province of Himachal Pradesh was proclaimed."]],
 rel:["s-suket","p-padamdev","ev-hp-formation","d-mandi"]},

/* ===== e10 Making Himachal ===== */
{id:"ev-hp-formation", era:"e10", y:1948.29, yr:"15 April 1948", t:"Himachal Pradesh is born", big:1,
 s:"Thirty hill states are integrated into a Chief Commissioner's Province with four districts.",
 blocks:[["p","The <b>Chief Commissioner's Province of Himachal Pradesh</b> came into being on <b>15 April 1948</b> by the integration of the hill states, with <b>four districts — Chamba, Mandi, Mahasu and Sirmaur</b>. The first Chief Commissioner was <b>N. C. Mehta</b>."],
 ["ul",["<b>Bilaspur was not included</b> — it remained a separate state until 1 July 1954.","<b>Shimla town was not included</b> — it was then in Punjab, and came to HP only in 1966.","The name is credited to <b>Acharya Diwakar Datt Sharma</b>: <i>him</i> (snow) + <i>achal</i> (abode) — the lap of the Himalaya."]],
 ["note","Disputed","The number of states integrated is given variously as 26, 28, 30 and 31 across sources, because feudatories and <i>thakurais</i> are counted differently. <b>30</b> is the most commonly accepted figure; if asked to justify, say 'about thirty princely states and thakurais'."]],
 rel:["ev-suket-satyagraha","ev-hhsrc","ev-bilaspur-merger","p-parmar","t-statehood"]},
{id:"ev-partc", era:"e10", y:1951, yr:"26 January 1950 · 1951", t:"Himachal becomes a Part C state",
 s:"Administered by a Lieutenant Governor with a 36-member Legislative Assembly.",
 blocks:[["p","On the commencement of the Constitution, Himachal Pradesh became a <b>Part C state</b> under a <b>Lieutenant Governor</b>. A <b>Legislative Assembly of 36 members</b> was provided under the Government of Part C States Act, 1951."],
 ["p","The <b>first election was held in 1952</b>; the Congress won 24 seats and <b>Dr. Y. S. Parmar became the first Chief Minister on 8 March 1952</b>."]],
 rel:["p-parmar","t-statehood","t-polity"]},
{id:"ev-bilaspur-merger", era:"e10", y:1954, yr:"1 July 1954", t:"Bilaspur merges as the fifth district",
 s:"The separate Part C state of Bilaspur is joined to Himachal Pradesh.",
 blocks:[["p","Bilaspur, a Part C state in its own right since 1948, was merged into Himachal Pradesh on <b>1 July 1954</b> under the Himachal Pradesh and Bilaspur (New State) Act, 1954, becoming its <b>fifth district</b>."]],
 rel:["s-kahlur","d-bilaspur","t-statehood"]},
{id:"ev-ut", era:"e10", y:1956, yr:"1 November 1956", t:"Himachal becomes a Union Territory", big:1,
 s:"The States Reorganisation Act abolishes the Part C category; the Assembly is dissolved and a Territorial Council replaces it.",
 blocks:[["p","Under the <b>States Reorganisation Act, 1956</b> the Part C category was abolished and Himachal Pradesh became a <b>Union Territory</b> on <b>1 November 1956</b>. The Legislative Assembly was dissolved and a <b>Territorial Council</b> set up in its place; the office of Chief Minister lapsed."],
 ["p","A legislature was restored under the <b>Government of Union Territories Act, 1963</b>, and <b>Y. S. Parmar returned as Chief Minister on 1 July 1963</b>."]],
 rel:["t-statehood","p-parmar","t-polity"]},
{id:"ev-kinnaur", era:"e10", y:1960, yr:"1 May 1960", t:"Kinnaur becomes the sixth district",
 s:"The upper Sutlej tract is separated from Mahasu district.",
 blocks:[["p","<b>Kinnaur</b> was carved out of <b>Mahasu</b> district on <b>1 May 1960</b>, recognising the distinct tribal character of the upper Sutlej valley. It was later given Scheduled Area status."]],
 rel:["d-kinnaur","t-tribes","t-statehood"]},
{id:"ev-punjab-reorg", era:"e10", y:1966, yr:"1 November 1966", t:"The Punjab Reorganisation Act doubles Himachal", big:1,
 s:"Kangra, Kullu, Shimla, Lahaul-Spiti, Nalagarh and parts of Una and Gurdaspur are transferred from Punjab.",
 blocks:[["p","The <b>Punjab Reorganisation Act, 1966</b> transferred the hill areas of Punjab to Himachal Pradesh on <b>1 November 1966</b> — the day Haryana was created and Chandigarh made a Union Territory."],
 ["ul",["<b>Kangra, Kullu, Lahaul & Spiti and Shimla</b> districts in full.","<b>Nalagarh</b> sub-division of Ambala district.","Parts of <b>Una tehsil</b> of Hoshiarpur district, and the Santokhgarh–Amb area.","<b>Dalhousie and Bakloh</b> from Gurdaspur district."]],
 ["p","Himachal now had <b>ten districts</b> and, for the first time, included <b>Shimla town</b>. The transfer also brought the <b>Bhakra and Pong</b> works and the bulk of the state's population."],
 ["note","Exam hook","1966 is the single most important administrative date after 1948. Remember what came: Kangra, Kullu, Lahaul-Spiti, Shimla, Nalagarh, Una parts, Dalhousie and Bakloh."]],
 rel:["d-kangra","d-kullu","d-shimla","d-lahaul","s-nalagarh","t-statehood","ev-lahore-treaty"]},
{id:"ev-statehood", era:"e10", y:1971, yr:"25 January 1971", t:"Himachal Pradesh becomes the 18th state", big:1,
 s:"Indira Gandhi proclaims statehood at the Ridge in Shimla; Y. S. Parmar becomes the first Chief Minister of the state.",
 blocks:[["p","The <b>State of Himachal Pradesh Act, 1970</b> was passed by Parliament on <b>18 December 1970</b> and received assent on <b>31 December 1970</b>. On <b>25 January 1971</b> Himachal Pradesh became the <b>eighteenth state of the Indian Union</b>, proclaimed by Prime Minister <b>Indira Gandhi</b> at the Ridge in Shimla."],
 ["p","<b>Dr. Y. S. Parmar</b>, who had led the demand since 1946, became the first Chief Minister of the full state. The <b>Himachal Pradesh High Court</b> came into existence the same day."],
 ["note","Exam hook","Act passed 18 December 1970; statehood 25 January 1971; 18th state. Parmar is 'the architect of Himachal Pradesh'."]],
 rel:["p-parmar","t-statehood","t-polity","d-shimla"]},
{id:"ev-reorg1972", era:"e10", y:1972.67, yr:"1 September 1972", t:"Reorganisation into twelve districts", big:1,
 s:"Una, Hamirpur and Solan are created; Mahasu is dissolved into Shimla.",
 blocks:[["p","On <b>1 September 1972</b> the districts were rearranged into the present twelve. <b>Kangra</b> was divided into <b>Kangra, Hamirpur and Una</b>; <b>Mahasu</b> was dissolved and merged with <b>Shimla</b>; and <b>Solan</b> was formed from parts of Mahasu, Shimla and the Nalagarh area."],
 ["note","Exam hook","Three districts share the birthday 1 September 1972: Una, Hamirpur and Solan. Mahasu is the district that no longer exists."]],
 rel:["d-una","d-hamirpur","d-solan","d-shimla","t-statehood"]},
{id:"ev-simla-agreement", era:"e10", y:1972.5, yr:"2 July 1972", t:"The Simla Agreement",
 s:"Indira Gandhi and Zulfikar Ali Bhutto sign the post-1971 settlement at Barnes Court, Shimla.",
 blocks:[["p","Signed at Shimla on <b>2 July 1972</b> between <b>Indira Gandhi</b> and <b>Zulfikar Ali Bhutto</b>, the agreement converted the 1971 ceasefire line into the <b>Line of Control</b> and committed both states to settling differences bilaterally. It is a national-affairs fact with a Himachal address."]],
 rel:["d-shimla","t-british-shimla"]},
{id:"ev-winter-capital", era:"e10", y:2017, yr:"19 January 2017", t:"Dharamshala declared the second capital",
 s:"Kangra's district headquarters becomes the winter capital of Himachal Pradesh.",
 blocks:[["p","<b>Dharamshala</b> was declared the <b>second (winter) capital</b> of Himachal Pradesh on <b>19 January 2017</b>, with the winter session of the Assembly held at Tapovan. It has been the seat of the <b>Central Tibetan Administration</b> since 1960."]],
 rel:["d-kangra","t-polity"]}
];


/* ---------- BATTLES, SIEGES & TREATIES ---------- */

/* winSide is the index into this record's own `sides` of the side that won.
   It exists because `winner` is prose for a reader and `outcome` reads from
   the hill states' point of view — Bhangani is outcome:"loss" while sides[0],
   Guru Gobind Singh, won it. Do not try to derive one from the other. */
D.battles = [
{id:"b-kangra1620", name:"Siege of Kangra Fort", kind:"siege", era:"e5", y:1620, yr:"1620", place:"kangrafort",
 sides:["Mughal Empire (Jahangir)","Kangra (Katoch)"], outcome:"win", winner:"Mughals", winSide:0,
 cause:"Akbar had failed to take Nagarkot; Jahangir made its capture a point of imperial prestige and a key to controlling the Punjab hills.",
 course:"The siege was pressed from 1615 by Murtaza Khan and then Suraj Mal, and completed by an army under Prince Khurram (the future Shah Jahan) with Raja Suraj Mal and Raja Jagat Singh of Nurpur. The garrison was starved into surrender.",
 result:"Kangra fort fell to the Mughals in 1620 — the first time it had been held by an outside power for any length of time. Jahangir visited in 1622, ordered a mosque built inside the fort, and considered building a residence in the valley. Nawab Ali Khan was made the first Mughal keeper.",
 sig:"Mughal authority now reached directly into the hills. Every hill state became tributary, and the pattern of paying tribute in exchange for internal autonomy was set — the same bargain the British would later write into sanads.",
 rel:["s-kangra","s-nurpur","ev-akbar-tribute","t-mughal-relations","d-kangra"]},

{id:"b-bhangani", name:"Battle of Bhangani", kind:"battle", era:"e5", y:1688, yr:"1688", place:"bhangani",
 sides:["Guru Gobind Singh","Confederacy of hill rajas under Bhim Chand of Kahlur"], outcome:"loss", winner:"Guru Gobind Singh", winSide:0,
 cause:"The hill rajas resented the Guru's growing military establishment at Paonta Sahib and his refusal to pay tribute to Bhim Chand of Kahlur, on whose former territory Anandpur stood.",
 course:"Fought near Paonta Sahib on the Yamuna in Sirmaur. Bhim Chand of Kahlur led the hill chiefs, joined by Fateh Shah of Garhwal; the Guru's force included Pathan mercenaries who deserted, and Udai Singh and Pir Budhu Shah's men who stayed.",
 result:"The hill confederacy was defeated. It was Guru Gobind Singh's first battle.",
 sig:"The first of the Guru's wars, and the beginning of the long quarrel between the Sikhs and the hill states that would run through Nadaun (1691) and Anandpur. Bhangani is the standard answer to 'Guru Gobind Singh's first battle' and it was fought in present-day Himachal Pradesh.",
 rel:["s-sirmaur","s-kahlur","ev-paonta","t-sikh-relations","d-sirmaur"]},

{id:"b-nadaun", name:"Battle of Nadaun", kind:"battle", era:"e5", y:1691, yr:"1691", place:"mahalmorian",
 sides:["Hill rajas + Guru Gobind Singh","Mughal force under Alif Khan"], outcome:"win", winner:"Hill rajas and the Guru", winSide:0,
 cause:"Bhim Chand of Kahlur and other hill chiefs refused the tribute demanded by the Mughal governor of Jammu; Alif Khan was sent to enforce it.",
 course:"Fought on the Beas at Nadaun (Hamirpur). Three years after fighting each other at Bhangani, Bhim Chand of Kahlur and Guru Gobind Singh fought on the same side against the Mughal detachment.",
 result:"Alif Khan was defeated and withdrew.",
 sig:"The only occasion on which the hill rajas and Guru Gobind Singh fought as allies — which is exactly why it is asked. Pair it with Bhangani: same principals, opposite sides, three years apart.",
 rel:["s-kahlur","ev-paonta","t-sikh-relations","d-hamirpur"]},

{id:"b-mahalmorian", name:"Battle of Mahal Morian", kind:"battle", era:"e7", y:1806, yr:"1806", place:"mahalmorian",
 sides:["Gorkhas under Amar Singh Thapa + hill chiefs","Kangra under Sansar Chand II"], outcome:"loss", winner:"Gorkhas", winSide:0,
 cause:"Sansar Chand had reduced most of the hill states to tribute. The chiefs — led by Kahlur — invited Amar Singh Thapa across the Sutlej to break him.",
 course:"The armies met at Mahal Morian in present-day Hamirpur district. Sansar Chand's forces were broken; he fled to Sujanpur Tira and then shut himself into Kangra fort.",
 result:"Katoch supremacy over the hills ended in a single afternoon. The Gorkhas overran the Kangra valley and besieged the fort for four years, but never took it.",
 sig:"The hinge of late hill history. It ends the Katoch golden age, brings the Gorkhas to the Beas, and forces Sansar Chand to call in Ranjit Singh in 1809 — which costs him the fort and hands Kangra to the Sikhs.",
 rel:["p-sansarchand","p-amarsingh","s-kangra","ev-gorkha-kangra","b-kangra1809","d-hamirpur"]},

{id:"b-kangra1809", name:"Relief of Kangra Fort", kind:"siege", era:"e6", y:1809, yr:"1809", place:"kangrafort",
 sides:["Sikhs under Ranjit Singh + Kangra","Gorkhas under Amar Singh Thapa"], outcome:"treaty", winner:"Sikhs", winSide:0,
 cause:"Sansar Chand, besieged in Kangra fort since 1806 and near starvation, appealed to Maharaja Ranjit Singh for relief.",
 course:"By the agreement concluded at Jwalamukhi, Ranjit Singh's army marched into the valley and drove the Gorkhas back across the Sutlej. The price was the fort itself.",
 result:"The Gorkhas withdrew east of the Sutlej permanently. Ranjit Singh took possession of Kangra fort and 66 villages; Sansar Chand became a Sikh tributary and retired to Sujanpur Tira.",
 sig:"Kangra passed from Katoch to Sikh hands and stayed there until the British annexation of 1846 — which is why Kangra was administered as part of Punjab and had to be transferred back to Himachal in 1966.",
 rel:["p-sansarchand","p-ranjitsingh","p-amarsingh","ev-jwalamukhi-treaty","t-sikh-relations","ev-punjab-reorg"]},

{id:"b-jaithak", name:"Battle of Jaithak", kind:"battle", era:"e7", y:1814.9, yr:"December 1814 – January 1815", place:"jaithak",
 sides:["British East India Company","Gorkhas under Ranjor Singh Thapa"], outcome:"loss", winner:"Gorkhas (tactically)", winSide:1,
 cause:"Jaithak fort above Nahan commanded Sirmaur; Major-General Martindell was ordered to take it as the first step of the western campaign.",
 course:"Ranjor Singh Thapa, son of Amar Singh Thapa, held the ridge with a small garrison. Two British assaults in December 1814 were thrown back with heavy loss; Martindell then settled into a blockade rather than storm the position.",
 result:"The British failed to take Jaithak by assault. The fort held out until Amar Singh Thapa's capitulation at Malaun in May 1815 made further resistance pointless.",
 sig:"With Kalanga, Jaithak is the episode that gave the Gorkha soldier his reputation in British eyes and led directly to Gorkha recruitment into the Company's army. It is the hardest fighting of the war on Himachal soil.",
 rel:["s-sirmaur","p-amarsingh","ev-anglo-gorkha","b-malaun","d-sirmaur"]},

{id:"b-malaun", name:"Fall of Malaun", kind:"battle", era:"e7", y:1815.4, yr:"15 May 1815", place:"malaun",
 sides:["British East India Company under David Ochterlony","Gorkhas under Amar Singh Thapa"], outcome:"win", winner:"British", winSide:0,
 cause:"Malaun, in Hindur (Nalagarh), was Amar Singh Thapa's headquarters west of the Sutlej and the last Gorkha stronghold in the Shimla hills.",
 course:"Ochterlony advanced methodically, detaching the hill chiefs from the Gorkhas with promises of restoration, and took the ridge position by position. Ramgarh fell first. In the assault on Malaun the veteran Gorkha commander Bhakti Thapa was killed leading a counter-attack.",
 result:"Amar Singh Thapa capitulated on 15 May 1815 and was allowed to march out with his arms and withdraw to Nepal. Many of his soldiers immediately took service with the British.",
 sig:"The end of Gorkha rule in the Himachal hills. The Nasiri battalion — later the 1st Gorkha Rifles — was raised from the surrendered troops and stationed at Subathu, and its Jutogh detachment mutinied in 1857.",
 rel:["p-amarsingh","p-ochterlony","s-nalagarh","ev-malaun","ev-1857","d-solan"]},

{id:"b-segauli", name:"Treaty of Segauli (Sugauli)", kind:"treaty", era:"e7", y:1816, yr:"Signed 2 Dec 1815 · ratified 4 March 1816", place:"malaun",
 sides:["British East India Company","Kingdom of Nepal"], outcome:"treaty", winner:"British", winSide:0,
 cause:"To end the Anglo-Gorkha War of 1814–16 and fix Nepal's boundaries permanently.",
 course:"Negotiated after the fall of Malaun and the Gorkha reverses in the east; signed at Segauli on 2 December 1815 and ratified on 4 March 1816 after a renewed British advance.",
 result:"Nepal ceded all territory west of the Kali river — Kumaon, Garhwal and the hill states up to the Sutlej — gave up Sikkim and much of the Tarai, accepted a British Resident at Kathmandu, and conceded the right to recruit Gorkhas into British service. Nepal lost roughly a third of its territory.",
 sig:"For Himachal this is the founding document of the colonial period. The hill states were restored to their rajas but as protected states holding British sanads; Subathu, Kotgarh, Kotkhai and the future site of Shimla were retained directly; and a Superintendent of Hill States was appointed.",
 rel:["ev-segauli","p-amarsingh","p-ochterlony","t-colonial-admin","t-gorkha"]},

{id:"b-lahore", name:"Treaty of Lahore", kind:"treaty", era:"e6", y:1846, yr:"9 March 1846", place:"kangrafort",
 sides:["British East India Company","Sikh Empire"], outcome:"treaty", winner:"British", winSide:0,
 cause:"To settle the First Anglo-Sikh War (1845–46) after the Sikh defeats at Ferozeshah, Aliwal and Sobraon.",
 course:"Imposed on the Lahore darbar after Sobraon. The Sikhs paid an indemnity, reduced their army, ceded the Jalandhar Doab and the hill country between the Beas and the Sutlej.",
 result:"Kangra, Kullu, Lahaul and Spiti, and the trans-Sutlej hill tracts passed to the East India Company and were constituted as the district of Kangra under the Punjab administration.",
 sig:"Kangra's hundred and twenty years inside Punjab begin here — and end with the Punjab Reorganisation Act of 1 November 1966.",
 rel:["ev-lahore-treaty","p-ranjitsingh","ev-punjab-reorg","t-colonial-admin","d-kangra"]},

{id:"b-shahpur", name:"Ram Singh Pathania's Rising", kind:"battle", era:"e9", y:1848, yr:"1848", place:"shahpurkandi",
 sides:["Nurpur rebels under Ram Singh Pathania","British East India Company"], outcome:"loss", winner:"British", winSide:1,
 cause:"The British had annexed Nurpur and pensioned off its royal house. Ram Singh, the wazir, rose in the name of the minor heir Jaswant Singh during the Second Anglo-Sikh War.",
 course:"He seized the fort of Shahpur Kandi and raised the Nurpur hills, evading British columns for months in the Dhameri country before being brought to action near Shahpur.",
 result:"Defeated after being betrayed, captured, and transported to Singapore, where he died in 1849.",
 sig:"The first armed resistance to British rule in the Himachal hills, and the event from which the syllabus dates the freedom movement in Himachal Pradesh — '1848 to 1948'.",
 rel:["p-ramsingh","s-nurpur","ev-ramsingh","t-freedom","d-kangra"]},

{id:"b-dhami", name:"The Dhami Firing", kind:"firing", era:"e9", y:1939.6, yr:"16 July 1939", place:"dhami",
 sides:["Dhami Praja Mandal","Rana Dalip Singh of Dhami"], outcome:"loss", winner:"The state, momentarily", winSide:1,
 cause:"The Rana banned the Dhami Prem Prachani Sabha. Bhagmal Sautha led a procession to Halog to present the Praja Mandal's demands and was arrested on the way.",
 course:"The crowd, angered by the arrest, pressed on to Halog Chowk. The Rana's men opened fire.",
 result:"Durga Das was killed and many were injured. Bhagmal Sautha, Mansa Ram and Dharam Das were arrested. Nehru took up the case and the lawyer Duni Chand was deputed to enquire; a delegation including Rajkumari Amrit Kaur carried it to Gandhi.",
 sig:"The first firing on a popular movement in the Himachal hills. It turned the Praja Mandal movement from a petitioning campaign into a national cause, and is the single most cited date of the hill freedom struggle.",
 rel:["ev-dhami","s-dhami","p-bhagmalsautha","p-amritkaur","t-freedom","d-shimla"]},

{id:"b-ghazni1009", name:"Sack of Nagarkot", kind:"battle", era:"e4", y:1009, yr:"1009", place:"kangrafort",
 sides:["Mahmud of Ghazni","Kangra (Katoch)"], outcome:"loss", winner:"Mahmud of Ghazni", winSide:0,
 cause:"The wealth accumulated in the Brajeshwari temple at Nagarkot, reported to Mahmud after his victory over the Hindu Shahi confederacy.",
 course:"Mahmud turned aside from the Punjab plains and invested Nagarkot, which surrendered after a short siege.",
 result:"The temple treasury was carried off — the Tarikh-i-Yamini of Utbi gives an extravagant inventory. The fort was later recovered by the hill chiefs.",
 sig:"The first Muslim invasion to reach the Himachal hills, and the first of the four famous captures of Kangra fort: 1009 Ghazni, 1360 Firoz Shah Tughlaq, 1620 Jahangir, 1809 Ranjit Singh.",
 rel:["ev-ghazni","s-kangra","d-kangra","t-temples"]},

{id:"b-tughlaq1360", name:"Firoz Shah Tughlaq's Raid on Nagarkot", kind:"battle", era:"e4", y:1360, yr:"1360", place:"kangrafort",
 sides:["Delhi Sultanate (Firoz Shah Tughlaq)","Kangra (Katoch)"], outcome:"loss", winner:"Delhi Sultanate", winSide:0,
 cause:"To reassert Sultanate authority over the hills after Muhammad bin Tughlaq's inconclusive expedition of 1337.",
 course:"Firoz Shah besieged the fort; the raja submitted and was restored as a tributary.",
 result:"The sultan took 1,300 Sanskrit manuscripts from the library of the Jwalamukhi temple, some of which were translated into Persian as the Dalail-i-Firoz Shahi.",
 sig:"The manuscript episode is the standard one-liner. Note the pairing: Muhammad bin Tughlaq 1337, Firoz Shah Tughlaq 1360.",
 rel:["ev-tughlaq","s-kangra","d-kangra","t-temples"]},

{id:"b-kalanga", name:"Battle of Kalanga (Nalapani)", kind:"battle", era:"e7", y:1814.8, yr:"31 October 1814", place:"jaithak",
 sides:["British East India Company under Rollo Gillespie","Gorkhas under Balbhadra Kunwar"], outcome:"loss", winner:"Gorkhas (tactically)", winSide:1,
 cause:"The opening British assault of the Anglo-Gorkha War, against the fort covering Dehra Dun.",
 course:"Major-General Rollo Gillespie attacked without waiting for his siege guns and was killed at the gate on 31 October 1814. Balbhadra Kunwar held out with about 600 men against a far larger force before cutting his way out.",
 result:"A British tactical defeat, though the position was abandoned. Gillespie was the most senior British officer killed in the war.",
 sig:"Though fought in present-day Uttarakhand, Kalanga is examined alongside Jaithak because the two defeats together forced the British to change their whole approach — Ochterlony's method of detaching the hill chiefs replaced frontal assault.",
 rel:["ev-anglo-gorkha","b-jaithak","t-gorkha","p-ochterlony"]},

{id:"b-anglosikh2", name:"Second Anglo-Sikh War", kind:"battle", era:"e6", y:1849, yr:"1848–49", place:"kangrafort",
 sides:["British East India Company","Sikh Empire"], outcome:"win", winner:"British", winSide:0,
 cause:"The revolt at Multan and the wider Sikh rising against the British residency established after 1846.",
 course:"Decided at Chillianwala and Gujrat. In the hills, several rajas who had backed the Sikhs were dispossessed.",
 result:"The Punjab was annexed. The hill states of Jaswan, Datarpur and Siba were annexed outright and their rulers pensioned; Ram Singh Pathania's rising in Nurpur was crushed in the same period.",
 sig:"The end of independent rule for the Katoch offshoot states in the lower hills. What survived after 1849 were the protected states holding sanads — the ones that would still exist to be merged in 1948.",
 rel:["s-jaswan","s-siba","s-datarpur","b-shahpur","t-colonial-admin"]},

{id:"b-suket1948", name:"The Suket Satyagraha", kind:"firing", era:"e9", y:1948.1, yr:"18 February 1948", place:"tattapani",
 sides:["Suket Praja Mandal under Pandit Padam Dev","Raja Lakshman Sen of Suket"], outcome:"win", winner:"The people's movement", winSide:0,
 cause:"Suket's ruler resisted accession to the proposed hill province after the other states had agreed at the Solan convention.",
 course:"Volunteers crossed into Suket from Tattapani on 18 February 1948 and marched on Sundernagar. The state's authority collapsed without serious resistance.",
 result:"Suket acceded. Within two months the Chief Commissioner's Province of Himachal Pradesh was proclaimed on 15 April 1948.",
 sig:"The last popular movement against a hill ruler and the one that completed the integration. Remember the trio: Tattapani, 18 February 1948, Pandit Padam Dev.",
 rel:["ev-suket-satyagraha","s-suket","p-padamdev","ev-hp-formation","d-mandi"]}
];


/* ---------- PEOPLE ---------- */
D.people = [
{id:"p-sansarchand", name:"Sansar Chand II", role:"Raja of Kangra", dates:"r. 1775–1823", era:"e6", tag:"Ruler",
 one:"The last great Katoch king — supreme in the hills for twenty years, then broken at Mahal Morian.",
 blocks:[["p","Succeeded at the age of ten in 1775 and recovered <b>Kangra fort in 1786</b> from Jai Singh Kanhaiya. Over the next two decades he reduced <b>Chamba, Mandi, Suket, Kullu, Kahlur, Nurpur, Guler, Jaswan, Siba and Kutlehr</b> to tribute — the widest reach any hill ruler achieved."],
 ["p","His ambition to build a Katoch kingdom in the plains brought him up against <b>Ranjit Singh</b>. Meanwhile the chiefs he had subdued invited the <b>Gorkhas</b> in; he was defeated at <b>Mahal Morian in 1806</b> and besieged in Kangra fort for four years. Buying Sikh relief in <b>1809</b> cost him the fort itself."],
 ["p","He spent his last years at <b>Sujanpur Tira</b> as a Sikh tributary. His court there was the greatest single patron of the <b>Kangra school of painting</b>, and the Gita Govinda and Bihari Satsai series were made for him."]],
 rel:["s-kangra","b-mahalmorian","b-kangra1809","ev-sansar-fort","t-pahari-painting","p-amarsingh","p-ranjitsingh"]},

{id:"p-amarsingh", name:"Amar Singh Thapa", role:"Gorkha commander-in-chief, west of the Kali", dates:"c. 1751–1816", era:"e7", tag:"Commander",
 one:"Conquered thirty hill states for Nepal and lost them all at Malaun.",
 blocks:[["p","The architect of Gorkha expansion west of the Kali. Between 1790 and 1805 he overran <b>Kumaon, Garhwal, Sirmaur and the Shimla hills</b> up to the Sutlej, and in <b>1806</b> defeated <b>Sansar Chand at Mahal Morian</b>."],
 ["p","He besieged Kangra fort for four years without taking it, and was driven back across the Sutlej by Ranjit Singh in <b>1809</b>. In the Anglo-Gorkha war he was outmanoeuvred by <b>Ochterlony</b>, who detached the hill chiefs from him one by one, and capitulated at <b>Malaun on 15 May 1815</b>."],
 ["note","Note","Distinguish him from <b>Bhimsen Thapa</b> (the Nepalese prime minister) and from his son <b>Ranjor Singh Thapa</b>, who defended Jaithak."]],
 rel:["ev-gorkha-sirmaur","b-mahalmorian","b-malaun","b-jaithak","t-gorkha","p-ochterlony"]},

{id:"p-ochterlony", name:"Sir David Ochterlony", role:"British commander, western front", dates:"1758–1825", era:"e7", tag:"Commander",
 one:"Won the Gorkha war in the hills by politics as much as by artillery.",
 blocks:[["p","Commanded the column that faced Amar Singh Thapa. Where Gillespie and Martindell assaulted forts and lost men, Ochterlony advanced methodically and <b>detached the hill chiefs from the Gorkhas by promising restoration</b> — a promise the sanads of 1815 kept."],
 ["p","He took Ramgarh and then Malaun, accepted Amar Singh Thapa's capitulation, and shaped the settlement that made the hill states British-protected states."]],
 rel:["b-malaun","b-segauli","p-amarsingh","t-colonial-admin"]},

{id:"p-ranjitsingh", name:"Maharaja Ranjit Singh", role:"Ruler of the Sikh Empire", dates:"1780–1839", era:"e6", tag:"Ruler",
 one:"Took Kangra fort as the price of rescuing Sansar Chand, and held the hills until 1846.",
 blocks:[["p","Extended Sikh authority over the western hill states. In <b>1809</b> he relieved Sansar Chand in Kangra fort, expelled the Gorkhas from the valley, and took <b>the fort and 66 villages</b> for himself. The hill rajas of Kangra, Nurpur, Guler, Jaswan, Datarpur, Siba, Kutlehr, Mandi and Kullu became his tributaries."],
 ["p","Sikh rule over Kangra lasted until the <b>Treaty of Lahore (1846)</b>, when it passed to the British."]],
 rel:["b-kangra1809","b-lahore","p-sansarchand","t-sikh-relations"]},

{id:"p-parmar", name:"Dr. Yashwant Singh Parmar", role:"First Chief Minister; architect of Himachal Pradesh", dates:"1906–1981", era:"e10", tag:"Statesman",
 one:"Led the demand for a hill province from 1946 and got statehood in 1971.",
 blocks:[["p","Born at Chanhalag in Sirmaur, trained in law and sociology (his doctoral work was on polyandry in the Himalaya), and a judge in Sirmaur state before entering politics."],
 ["p","Elected <b>president of the Himalayan Hill States Regional Council</b> at Mandi in <b>March 1946</b>, he argued the case for a single hill administrative unit against both the rulers and the Punjab lobby. He became the <b>first Chief Minister on 8 March 1952</b>, returned to office in <b>1963</b>, and was Chief Minister when Himachal became the <b>18th state on 25 January 1971</b>."],
 ["ul",["Served as Chief Minister 1952–56, 1963–71 (UT) and 1971–77 (state).","The <b>Dr. Y. S. Parmar University of Horticulture and Forestry</b>, Nauni (Solan), is named after him.","He is titled the <b>architect / father of Himachal Pradesh</b>."]]],
 rel:["ev-hhsrc","ev-statehood","ev-hp-formation","t-statehood","t-polity","p-padamdev"]},

{id:"p-padamdev", name:"Pandit Padam Dev", role:"Praja Mandal leader; 'Himachal Kesari'", dates:"1901–1983", era:"e9", tag:"Freedom fighter",
 one:"Secretary of the hill states' council and leader of the Suket Satyagraha.",
 blocks:[["p","One of the central organisers of the hill freedom movement. Secretary of the <b>Himalayan Riyasati Praja Mandal</b> and then of the <b>Himalayan Hill States Regional Council</b> formed at Mandi in 1946."],
 ["p","He led the <b>Suket Satyagraha</b> from <b>Tattapani on 18 February 1948</b>, the last movement against a hill ruler, which completed the integration of the states. He later served as a minister in Parmar's government."]],
 rel:["ev-suket-satyagraha","ev-hhsrc","s-suket","p-parmar","t-freedom"]},

{id:"p-kanshiram", name:"Baba Kanshi Ram", role:"Poet and freedom fighter; 'Pahari Gandhi'", dates:"1882–1943", era:"e9", tag:"Freedom fighter",
 one:"Wore black until independence and sang the hills into the national movement.",
 blocks:[["p","Born at Dada Siba in Kangra. A poet in Pahari who used verse as political organising, he joined the national movement early and was jailed repeatedly."],
 ["p","Injured at the <b>Sujanpur Tira conference of 1927</b>, he took a vow to <b>wear only black clothes until India was free</b> — hence his popular name. <b>Sarojini Naidu</b> gave him the title <b>'Pahari Bulbul'</b> and Gandhi's circle called him the <b>'Pahari Gandhi'</b>. He also took part in the Kunihar agitation of 1920."]],
 rel:["ev-kunihar","t-freedom","d-kangra"]},

{id:"p-bhagmalsautha", name:"Bhagmal Sautha", role:"Leader of the Dhami Praja Mandal", dates:"1899–1971", era:"e9", tag:"Freedom fighter",
 one:"His arrest triggered the Dhami firing of 16 July 1939.",
 blocks:[["p","President of the <b>Himalayan Riyasati Praja Mandal</b> and the leading figure of the Dhami movement. When the Rana banned the <b>Dhami Prem Prachani Sabha</b>, Sautha led a procession to Halog to present the people's demands and was arrested on the way — the arrest that provoked the crowd and the firing of <b>16 July 1939</b>."],
 ["p","He was imprisoned along with <b>Mansa Ram</b> and <b>Dharam Das</b>."]],
 rel:["ev-dhami","b-dhami","s-dhami","t-freedom"]},

{id:"p-stokes", name:"Satyanand Stokes", role:"Social reformer; brought the apple to Himachal", dates:"1882–1946", era:"e9", tag:"Reformer",
 one:"An American Quaker who settled at Kotgarh, fought begar, and planted the orchards that made modern Himachal.",
 blocks:[["p","Born <b>Samuel Evans Stokes</b> in Philadelphia, he came to India in 1904, settled at <b>Kotgarh</b> in the Shimla hills, married locally and later converted to Hinduism, taking the name <b>Satyanand</b>."],
 ["p","He campaigned against <b>begar</b> (forced labour) and was the <b>only American to be a member of the All India Congress Committee</b>; he was imprisoned after the 1921 non-cooperation movement."],
 ["p","In <b>1916</b> he introduced <b>Red Delicious apple stock</b> from Louisiana at Kotgarh. Apple cultivation spread from there through Shimla, Kinnaur, Kullu and Mandi and is now the backbone of the rural economy — which makes Stokes a figure in both the history and the economy papers."]],
 rel:["ev-dujjam","t-horticulture","t-freedom","d-shimla"]},

{id:"p-ramsingh", name:"Ram Singh Pathania", role:"Wazir of Nurpur; leader of the 1848 revolt", dates:"d. 1849", era:"e9", tag:"Freedom fighter",
 one:"Raised the first armed resistance to British rule in the Himachal hills.",
 blocks:[["p","Rose in <b>1848</b> in the name of the dispossessed Nurpur heir <b>Jaswant Singh</b>, seized Shahpur Kandi fort and held the Nurpur hills against British columns. Defeated near <b>Shahpur</b> after being betrayed, he was transported to <b>Singapore</b>, where he died in 1849."],
 ["p","The freedom-movement period in the HPAS syllabus — <b>1848 to 1948</b> — is dated from his rising."]],
 rel:["ev-ramsingh","b-shahpur","s-nurpur","t-freedom"]},

{id:"p-bhimsingh", name:"Subedar Bhim Singh", role:"Leader of the 1857 rising at Kasauli", dates:"fl. 1857", era:"e8", tag:"Rebel",
 one:"Began the revolt of 1857 in the hills and was sheltered by the Raja of Bushahr.",
 blocks:[["p","Commanded the guard at <b>Kasauli</b>. In 1857 he led about eighty men, seized the government treasury and joined the <b>Nasiri battalion</b> at <b>Jutogh</b> near Shimla, forcing the European residents of Shimla to flee."],
 ["p","After the rising collapsed he was sheltered by Raja <b>Shamsher Singh of Bushahr</b> — the one hill ruler who gave the British no assistance."]],
 rel:["ev-1857","s-bushahr","d-solan","t-freedom"]},

{id:"p-amritkaur", name:"Rajkumari Amrit Kaur", role:"Congress leader; India's first Health Minister", dates:"1889–1964", era:"e9", tag:"Statesman",
 one:"Gandhi's secretary for sixteen years, and the Shimla-based voice of the hill movements in Delhi.",
 blocks:[["p","Daughter of Raja Harnam Singh of Kapurthala, educated in England and long resident at <b>Manorville, Shimla</b>. She was Gandhi's secretary for sixteen years, took part in the Dandi and Quit India movements, and was imprisoned."],
 ["p","She carried the <b>Dhami firing</b> to Gandhi and Nehru. As a member of the Constituent Assembly and then <b>independent India's first Health Minister (1947–57)</b>, she founded <b>AIIMS New Delhi</b> and was the first woman to preside over the World Health Assembly."]],
 rel:["ev-dhami","d-shimla","t-freedom","t-british-shimla"]},

{id:"p-yashpal", name:"Yashpal", role:"Revolutionary and Hindi novelist", dates:"1903–1976", era:"e9", tag:"Revolutionary",
 one:"HSRA member turned major Hindi novelist; author of Jhootha Sach.",
 blocks:[["p","Born at Firozpur to a family from Hamirpur, he joined the <b>Hindustan Socialist Republican Association</b> with Bhagat Singh and Chandrashekhar Azad, and became its commander after Azad's death. Arrested in 1932, he was sentenced to a long term."],
 ["p","In prison and after, he became one of the major Hindi novelists of the century; <b>Jhootha Sach</b> is his best-known work."]],
 rel:["t-freedom","d-hamirpur"]},

{id:"p-hirdaram", name:"Bhai Hirda Ram", role:"Ghadar revolutionary, Mandi Conspiracy", dates:"d. 1915 (sentence commuted)", era:"e8", tag:"Revolutionary",
 one:"Condemned to death for the Mandi Conspiracy of 1914–15.",
 blocks:[["p","A leading figure of the <b>Mandi Conspiracy</b>, the Ghadar party's plan for a rising in Mandi and Suket. He was sentenced to death; the sentence was commuted to transportation for life. <b>Swami Krishnanand (Hardev)</b> was the other principal figure of the affair."]],
 rel:["ev-mandi-conspiracy","s-mandi","t-freedom","d-mandi"]},

{id:"p-suratsingh", name:"Vaid Surat Singh", role:"Leader of the Pajhota agitation", dates:"fl. 1942", era:"e9", tag:"Freedom fighter",
 one:"Led Sirmaur's 'Bhai do na pai' movement — Quit India in the hills.",
 blocks:[["p","Led the <b>Pajhota agitation of 1942</b> in Sirmaur against the raja's support for the British war effort, with <b>Laxmi Singh, Miyan Chuchu and Basti Ram Pahari</b>. The slogan was <b>'Bhai do, na pai'</b>. The movement kept the state administration out of the Pajhota area for several months and is treated as an extension of the Quit India Movement."]],
 rel:["ev-pajhota","s-sirmaur","t-freedom","d-sirmaur"]},

{id:"p-hume", name:"Allan Octavian Hume", role:"Civil servant; founder of the Indian National Congress", dates:"1829–1912", era:"e8", tag:"Colonial",
 one:"Planned the Congress from Rothney Castle in Shimla.",
 blocks:[["p","A retired Bengal civil servant and ornithologist who lived at <b>Rothney Castle</b> on Jakhoo hill, Shimla. His correspondence and his 1883 open letter to the graduates of Calcutta University led to the founding of the <b>Indian National Congress in 1885</b>."],
 ["p","His bird collection, assembled at Shimla, went to the British Museum and remains one of the largest ever made in India."]],
 rel:["t-british-shimla","d-shimla"]},

{id:"p-nainsukh", name:"Nainsukh of Guler", role:"Pahari painter", dates:"c. 1710–1778", era:"e6", tag:"Artist",
 one:"The painter who turned the Pahari idiom from stylised to observed.",
 blocks:[["p","Son of <b>Pandit Seu</b> and brother of <b>Manaku</b>, Nainsukh left Guler to work for <b>Raja Balwant Singh of Jasrota</b>, producing an intimate, closely observed record of his patron's daily life that has no parallel in Indian painting."],
 ["p","The workshop of Seu, Manaku and Nainsukh carried the Pahari tradition from the hot, flat <b>Basohli</b> manner to the cool naturalism of <b>Guler</b>, out of which the <b>Kangra school</b> emerged in the 1780s under Sansar Chand."]],
 rel:["s-guler","t-pahari-painting","p-sansarchand"]},

{id:"p-meruvarman", name:"Meru Varman", role:"Raja of Chamba (Bharmour)", dates:"c. 680 CE", era:"e4", tag:"Ruler",
 one:"Built the Chaurasi temples at Bharmour; his artist Gugga cast their brass images.",
 blocks:[["p","The most important early ruler of Chamba. He built the shrines of the <b>Chaurasi complex at Bharmour</b> — <b>Lakshana Devi</b>, <b>Narsingh</b> and <b>Ganesha</b> — and the <b>Shakti Devi temple at Chhatrari</b>. The brass images were cast by the artist <b>Gugga</b>, whose name appears in the inscriptions."],
 ["p","The Meru Varman inscriptions are the <b>oldest firmly dated records in Himachal Pradesh</b>."]],
 rel:["s-chamba","ev-chamba-founded","t-temples","d-chamba"]},

{id:"p-ajbarsen", name:"Ajbar Sen", role:"Raja of Mandi", dates:"r. 1499–1534", era:"e5", tag:"Ruler",
 one:"Founded Mandi town in 1526 — the year of the first battle of Panipat.",
 blocks:[["p","Moved the Sena seat across the Beas from Bhiuli and laid out <b>Mandi town in 1526</b>, building the <b>Bhootnath temple</b> at its centre. The town's concentration of stone shikhara temples earned it the name <b>Choti Kashi</b>."]],
 rel:["s-mandi","ev-mandi-founded","d-mandi","t-temples"]},

{id:"p-sidhsen", name:"Sidh Sen", role:"Raja of Mandi", dates:"r. 1684–1727", era:"e5", tag:"Ruler",
 one:"The most powerful ruler of Mandi; received Guru Gobind Singh at his court.",
 blocks:[["p","Extended Mandi at the expense of its neighbours and was reputed a tantric of great power. He received <b>Guru Gobind Singh</b> at Mandi, and the state's Sikh associations — the Rewalsar connection among them — date from his reign."]],
 rel:["s-mandi","t-sikh-relations","d-mandi"]},

{id:"p-kehrisingh", name:"Kehri Singh", role:"Raja of Bushahr", dates:"r. 1639–1696", era:"e5", tag:"Ruler",
 one:"Won the title Chhatrapati from Aurangzeb and opened the Tibet trade that became the Lavi fair.",
 blocks:[["p","The greatest ruler of Bushahr. He received the title <b>Chhatrapati</b> from <b>Aurangzeb</b>, and concluded a <b>trade treaty with Tibet</b> that gave Bushahr merchants privileged access across the passes."],
 ["p","The <b>Lavi fair at Rampur</b>, still the state's great trans-Himalayan trade fair, is traced to this agreement."]],
 rel:["s-bushahr","t-fairs","d-kinnaur","t-mughal-relations"]},

{id:"p-bhurisingh", name:"Bhuri Singh", role:"Raja of Chamba", dates:"r. 1904–1919", era:"e8", tag:"Ruler",
 one:"Founded the Bhuri Singh Museum in 1908, which preserved the Chamba record.",
 blocks:[["p","Founded the <b>Bhuri Singh Museum at Chamba in 1908</b>, on the advice of the archaeologist <b>J. Ph. Vogel</b>, to house the state's inscriptions, copper plates, Pahari paintings and Chamba rumals. It remains the single most important collection for the early history of the region."]],
 rel:["s-chamba","d-chamba","t-pahari-painting","t-ancientsources"]},

{id:"p-virbhadra", name:"Virbhadra Singh", role:"Chief Minister of Himachal Pradesh", dates:"1934–2021", era:"e10", tag:"Statesman",
 one:"Six terms as Chief Minister — the longest-serving in the state's history.",
 blocks:[["p","Of the Bushahr royal house (titular Raja of Rampur Bushahr). He served <b>six non-consecutive terms as Chief Minister</b> — the longest tenure in Himachal's history — and was also a Union minister. His career, with <b>Shanta Kumar</b>'s and <b>Prem Kumar Dhumal</b>'s, frames HP's post-1977 two-party politics."]],
 rel:["t-polity","s-bushahr","t-statehood"]},

{id:"p-sankhyan", name:"Daulat Ram Sankhyan", role:"Praja Mandal leader, Bilaspur", dates:"fl. 1945–48", era:"e9", tag:"Freedom fighter",
 one:"Led the Bilaspur Praja Mandal and the movement for Bilaspur's merger.",
 blocks:[["p","Founded the <b>Bilaspur Praja Mandal in 1945</b> with <b>Narotam Dutt Shastri</b>, and led the agitation against Raja Anand Chand's administration. Bilaspur remained a separate Part C state until its merger with Himachal Pradesh on <b>1 July 1954</b>."]],
 rel:["ev-bilaspur-merger","s-kahlur","t-freedom","d-bilaspur"]}
];

